INSERT INTO `db_script` (`id`,`name`,`datasource_id`,`sql_content`,`return_limit`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`uid`) VALUES (1,'演示-订单明细',1,'SELECT o.order_no, c.name AS customer_name, p.name AS product_name, o.quantity, o.amount, o.status, o.order_date\nFROM demo_order o\nJOIN demo_customer c ON c.id = o.customer_id\nJOIN demo_product p ON p.id = o.product_id\nORDER BY o.order_date DESC',50,10,'演示用数据库脚本',NULL,'2026-10-25 21:27:18','2026-10-25 21:27:18',1,'1b80a87a-6882-4ef2-b7b1-c0c5a902bd70');
INSERT INTO `db_script` (`id`,`name`,`datasource_id`,`sql_content`,`return_limit`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`uid`) VALUES (2,'演示-按状态查订单',1,'SELECT o.order_no, c.name AS customer_name, p.name AS product_name, o.quantity, o.amount, o.status, o.order_date\nFROM demo_order o\nJOIN demo_customer c ON c.id = o.customer_id\nJOIN demo_product p ON p.id = o.product_id\nWHERE o.status = \'${_input.status}\'\nORDER BY o.order_date DESC',50,10,'演示用数据库脚本',NULL,'2026-10-25 21:27:18','2026-10-25 21:27:18',1,'ecc8e144-25a0-4946-9e6a-2855c2a59ee2');
INSERT INTO `db_script` (`id`,`name`,`datasource_id`,`sql_content`,`return_limit`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`uid`) VALUES (3,'演示-订单状态统计',1,'SELECT status, COUNT(*) AS order_count, SUM(amount) AS total_amount\nFROM demo_order\nGROUP BY status\nORDER BY status',50,10,'演示用数据库脚本',NULL,'2026-10-25 21:27:18','2026-10-25 21:27:18',1,'5b8e2f0e-0441-44b5-9559-842b73fa7bc0');
INSERT INTO `db_script` (`id`,`name`,`datasource_id`,`sql_content`,`return_limit`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`uid`) VALUES (4,'演示-更新订单备注',1,'UPDATE demo_order\nSET remark = \'${global_demo_greeting}\'\nWHERE order_no = \'DEMO-2001\'',50,10,'演示用数据库脚本',NULL,'2026-10-25 21:27:18','2026-10-25 21:27:18',1,'eb8bcaf7-d16a-44e9-b688-2df4616fe3cc');
