INSERT INTO `db_script` (`id`,`name`,`datasource_id`,`sql_content`,`return_limit`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`uid`) VALUES (6,'演示-内联查询',1,'SELECT order_no, status, amount\nFROM demo_order\nORDER BY id',50,10,'流程 08 内联 SQL',10,'2026-10-25 21:31:40','2026-10-25 21:31:40',1,'fac175b7-b6ac-4ba8-9ff0-54f9a49162b8');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (2,'TC635B56FC9B96','DemoStringUtil','class DemoStringUtil {\n    static String trimAndUpper(String s) {\n        if (s == null) return \'\'\n        return s.trim().toUpperCase()\n    }\n    static String maskName(String s) {\n        if (s == null) return \'\'\n        def t = s.trim()\n        if (t.length() <= 1) return \'*\'\n        return t.substring(0, 1) + (\'*\' * (t.length() - 1))\n    }\n}',NULL,'演示工具类：字符串去空格/转大写/姓名脱敏',NULL,'2026-10-25 21:29:24','2026-10-25 21:29:24',0,1,'DemoStringUtil','bbc02b06-7dc5-4ef5-ada3-11abc9e2977d');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (3,'PSD1878C71206D','演示-订单转换','def execute() {\n    def rows = orderList ?: []\n    log.info(\"订单转换开始，共 {} 条\", rows.size())\n    def result = rows.collect { r ->\n        [order_no: r.order_no, customer_name: r.customer_name, product_name: r.product_name,\n         quantity: r.quantity, amount: r.amount, status: r.status, order_date: r.order_date]\n    }\n    log.info(\"订单转换完成，共 {} 条\", result.size())\n    return result\n}',NULL,'演示用程序脚本',NULL,'2026-10-25 21:29:24','2026-10-25 21:29:24',1,0,NULL,'c066aba9-6be4-42dd-93df-a70db20f8040');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (4,'PS81740418408A','演示-订单汇总','import groovy.json.JsonSlurper\n\ndef execute() {\n    def rows = binding.hasVariable(\'orders\') ? orders : _input\n    if (rows instanceof String) {\n        try { rows = new JsonSlurper().parseText(rows) } catch (e) { rows = [] }\n    }\n    if (rows == null) rows = []\n    if (rows instanceof Map) rows = [rows]\n    def total = 0.0\n    def byStatus = [:]\n    rows.each { r ->\n        total += (r.amount ?: 0) as double\n        def s = r.status ?: \'UNKNOWN\'\n        byStatus[s] = (byStatus[s] ?: 0) + 1\n    }\n    total = Math.round(total * 100) / 100.0\n    log.info(\"订单汇总：{} 条，总金额 {}\", rows.size(), total)\n    return [count: rows.size(), totalAmount: total, byStatus: byStatus]\n}',NULL,'演示用程序脚本',NULL,'2026-10-25 21:29:24','2026-10-25 21:29:24',1,0,NULL,'75905883-78c1-4a9e-a489-5a998163c977');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (5,'PS3383E797EED6','演示-Excel解析','def execute() {\n    if (!binding.hasVariable(\'_fileStream\') || _fileStream == null) {\n        return [[error: \'请先上传 Excel 文件\']]\n    }\n    def rows = excelUtil.parse(_fileStream)\n    log.info(\"Excel 解析完成，共 {} 行\", rows.size())\n    rows.each { row ->\n        row.处理结果 = \'已处理\'\n    }\n    return rows\n}',NULL,'演示用程序脚本',NULL,'2026-10-25 21:29:24','2026-10-25 21:29:24',1,0,NULL,'a9f1a398-bf46-43ca-883e-9bdb53513c8f');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (6,'PS0B1FBFA6AE30','演示-统计格式化','def execute() {\n    def rows = stats ?: []\n    def totalOrders = 0\n    def totalAmount = 0.0\n    rows.each { r ->\n        totalOrders += (r.order_count ?: 0) as int\n        totalAmount += (r.total_amount ?: 0) as double\n    }\n    totalAmount = Math.round(totalAmount * 100) / 100.0\n    log.info(\"统计格式化：{} 个状态，{} 笔订单\", rows.size(), totalOrders)\n    return [summary: rows, totalOrders: totalOrders, totalAmount: totalAmount, env: _env_code, generatedAt: dateUtil.now()]\n}',NULL,'演示用程序脚本',NULL,'2026-10-25 21:29:24','2026-10-25 21:29:24',1,0,NULL,'cf040651-dd1b-479d-83cf-0e11917c9388');
INSERT INTO `program_script` (`id`,`script_id`,`name`,`script_content`,`query_timeout`,`remark`,`flow_id`,`create_time`,`update_time`,`user_id`,`is_tool`,`tool_class_name`,`uid`) VALUES (8,'PS22251A4E65C7','演示-内联转换','def execute() {\n    def name = _input?.name ?: \'Arbor\'\n    def rows = inlineRows ?: []\n    log.info(\"内联程序执行: name={}, rows={}\", name, rows.size())\n    return [\n        greeting: greeting,\n        envId: _env,\n        envCode: _env_code,\n        inputName: name,\n        upperName: DemoStringUtil.trimAndUpper(name),\n        maskedName: DemoStringUtil.maskName(name),\n        orderCount: rows.size(),\n        firstOrder: rows.isEmpty() ? null : rows[0].order_no\n    ]\n}',NULL,'流程 08 内联程序',10,'2026-10-25 21:31:40','2026-10-25 21:31:40',1,0,NULL,'c232ee13-bfbb-48b3-957d-9dae1ea6f6bb');
